import random
import time
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class VersionedValue:
    value: str
    timestamp: float
    version: int

@dataclass
class Node:
    node_id: int
    store: dict = field(default_factory=dict)
    is_available: bool = True

    def write(self, key: str, value: str, version: int) -> bool:
        if not self.is_available:
            return False
        self.store[key] = VersionedValue(value, time.time(), version)
        return True

    def read(self, key: str) -> Optional[VersionedValue]:
        if not self.is_available:
            return None
        # Simulate network latency
        time.sleep(random.uniform(0.001, 0.01))
        return self.store.get(key)

class QuorumKVStore:
    def __init__(self, n: int, w: int, r: int):
        self.nodes = [Node(i) for i in range(n)]
        self.N, self.W, self.R = n, w, r
        self._version = 0
        assert w + r > n, "W + R must be > N for strong consistency"

    def write(self, key: str, value: str) -> bool:
        self._version += 1
        successes = sum(
            node.write(key, value, self._version)
            for node in self.nodes
        )
        return successes >= self.W  # Quorum write success

    def read(self, key: str) -> Optional[str]:
        results = [
            node.read(key) for node in self.nodes
        ]
        valid = [r for r in results if r is not None]
        if len(valid) < self.R:
            return None  # Quorum not met
        # Return the value with the highest version (latest)
        latest = max(valid, key=lambda v: v.version)
        return latest.value

# N=3, W=2, R=2 → W+R=4 > N=3 → quorum consistency guaranteed
store = QuorumKVStore(n=3, w=2, r=2)
store.nodes[2].is_available = False  # Simulate one node down

store.write("user:1001", "Alice")
print(store.read("user:1001"))  # Still works: 2 out of 3 nodes respond

import hashlib
from bisect import bisect_right, insort
from collections import defaultdict

class ConsistentHashRing:
    def __init__(self, virtual_nodes: int = 150):
        self.virtual_nodes = virtual_nodes
        self.ring: list[int] = []      # sorted hash positions
        self.hash_to_node: dict[int, str] = {}
        self.node_keys: dict[str, list[int]] = defaultdict(list)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node: str):
        for i in range(self.virtual_nodes):
            vh = self._hash(f"{node}#{i}")
            insort(self.ring, vh)
            self.hash_to_node[vh] = node
            self.node_keys[node].append(vh)
        print(f"Added node '{node}' with {self.virtual_nodes} virtual nodes")

    def remove_node(self, node: str):
        for vh in self.node_keys.pop(node, []):
            self.ring.remove(vh)
            del self.hash_to_node[vh]
        print(f"Removed node '{node}'")

    def get_node(self, key: str) -> str:
        if not self.ring:
            raise Exception("No nodes in ring")
        h = self._hash(key)
        # Find first position >= h (wrap around to 0 if needed)
        idx = bisect_right(self.ring, h) % len(self.ring)
        return self.hash_to_node[self.ring[idx]]

# Demo: adding a new shard disrupts minimal data
ring = ConsistentHashRing(virtual_nodes=100)
ring.add_node("shard-1")
ring.add_node("shard-2")
ring.add_node("shard-3")

# Before adding shard-4
keys = [f"user:{i}" for i in range(1000)]
before = {k: ring.get_node(k) for k in keys}

ring.add_node("shard-4")  # Add new shard

after = {k: ring.get_node(k) for k in keys}
moved = sum(1 for k in keys if before[k] != after[k])
print(f"Keys remapped: {moved}/1000 ({moved/10:.1f}%)")  # ~25%, not 100%

import hashlib
import redis
import string
from typing import Optional

# --- URL Shortener: Base62 encoding ---
BASE62_CHARS = string.digits + string.ascii_letters  # 0-9, a-z, A-Z

def encode_base62(num: int) -> str:
    if num == 0:
        return BASE62_CHARS[0]
    result = []
    while num:
        result.append(BASE62_CHARS[num % 62])
        num //= 62
    return ''.join(reversed(result))

def decode_base62(s: str) -> int:
    return sum(BASE62_CHARS.index(c) * (62 ** i)
               for i, c in enumerate(reversed(s)))

# URL Shortener service
class UrlShortener:
    def __init__(self, redis_client: redis.Redis):
        self.r = redis_client
        self._counter_key = "url:counter"

    def shorten(self, long_url: str) -> str:
        # Check if already shortened
        existing_id = self.r.hget("url:long_to_id", long_url)
        if existing_id:
            return encode_base62(int(existing_id))

        url_id = self.r.incr(self._counter_key)  # Atomic increment
        short_code = encode_base62(url_id)

        # Bidirectional mapping
        self.r.hset("url:id_to_long", url_id, long_url)
        self.r.hset("url:long_to_id", long_url, url_id)
        return short_code

    def resolve(self, short_code: str) -> Optional[str]:
        url_id = decode_base62(short_code)
        return self.r.hget("url:id_to_long", url_id)

# --- Twitter Timeline Fan-out on Write ---
class TimelineService:
    TIMELINE_MAX = 800  # Keep last 800 tweets per user

    def __init__(self, redis_client: redis.Redis):
        self.r = redis_client

    def post_tweet(self, user_id: str, tweet_id: str, timestamp: float,
                   follower_ids: list[str]):
        # Fan-out: push tweet to all followers' timelines
        pipe = self.r.pipeline()
        for follower_id in follower_ids:
            key = f"timeline:{follower_id}"
            pipe.zadd(key, {tweet_id: timestamp})  # score = timestamp
            pipe.zremrangebyrank(key, 0, -(self.TIMELINE_MAX + 1))  # Keep max
        pipe.execute()

    def get_timeline(self, user_id: str, count: int = 20) -> list[str]:
        key = f"timeline:{user_id}"
        # ZRANGE with REV returns newest first
        return self.r.zrange(key, 0, count - 1, rev=True)

# Demo
r = redis.Redis()
shortener = UrlShortener(r)
code = shortener.shorten("https://example.com/very/long/url")
print(f"Short code: {code}")
print(f"Resolved: {shortener.resolve(code)}")
